# -*- coding: utf-8 -*-
"""Stage 3 merge for report 79 (Habit Tracker – Ripples / Checker, Mykola Harmash)."""
import json
C = {x["id"]: x for x in json.load(open("Tools/prd_ledger/canonical.json"))}
def ext(cid, text):
    if text not in C[cid]["statement"]: C[cid]["statement"] += text
def add(cid, section, title, statement):
    if cid in C: return
    C[cid] = dict(id=cid, title=title, statement=statement, section=section, cards=[], reports=[], merged_from=[])

add("C297", "product-rule", "A free cap's acceptability is set by the bundle around it — the same number reads as generous or as a wall depending on what else is free; moving a loved feature behind the wall changes sentiment as much as changing the number",
    "Report 79 (Ripples / Checker, 172 reviews): the free tier was three boards for the whole 770-day window and three reviewers on three storefronts state the number — in October 2024 and July 2025 as generosity ('for widgets and 3 habits without limitations'; 'three habits… without huge limitations', both 5★), in January 2026 as 'met 3 boards ben je totaal niks' (3★). What changed between those dates was not the cap but the home-screen widget — the single most-praised feature in the corpus (PRAISE_WIDGET 27, 15.70%, mean 5.00★, not one below 5) — moving behind the paywall in a 101-day window (2025-07-16 → 2025-10-25); paywall-shape complaints went from 0 of 110 reviews in the first era to ~10% of reviews after, the one explicit upgrade in the corpus was 'for more boards' (the cap was converting on its own), and a 4★ proposes the compromise himself: 'make 2 widgets available in free version, one the bigger one and one the minimalist one'. 'The cap is not the lever that broke; the bundle around it is.' §8.4.1: a widget is a daily impression of the product — removing it from the free tier removes the strongest retention and word-of-mouth surface in exchange for pressure on a cap that already worked. Related: [[C007]] (generous fixed cap), [[C222]] (hard cap with a pressure valve), [[C293]] (raising a cap does not buy back sentiment), [[C001]] (never move a free feature behind the paywall), [[C009]] (basic widgets are free).")

add("C298", "do", "A public roadmap converts — and becomes a promise users hold you to",
    "Report 79 (Ripples / Checker): PRAISE_ROADMAP 17 (9.88%, mean 4.94★) — reviewers repeatedly cite a public roadmap as a reason for confidence and for buying: 'following a roadmap full of nice upgrades'; 'what I personally miss (notes and custom units) is already planned by the developer! So I'll probably buy the full version soon'; one bought and then said they were waiting on the roadmap ('чекатиму на здійснення усього задуманого по роудмепу'); three purchase intents were conditional on named roadmap items (reminders + sync; notes + custom units; Russian) and all three later shipped. The counterweight is a 3★ whose entire text is 'Please complete roadmap', and a solo developer's pipeline that ships incremental asks (notes, reminders, compact widgets, start-of-day, multi-board view — mostly within 12–18 months, one reviewer editing the review up: 'so happy to have compact boards now!') but leaves the structural ones (Watch, iPad, import) open. Related: [[C196]] (a subscription is a promise of continued delivery — back it with a visible cadence), [[C059]] (be visibly responsive), [[C239]] (a personal origin story builds trust and turns a later gate into a betrayal).")

ext("C001", " Report 79 (Ripples / Checker): the home-screen widget — praised in 27 reviews at a perfect 5.00★ — was free until ~mid-2025 ('free for widgets and 3 habits without limitations'; 'Widget without premium(powerpack)') and then gated: 'Useless if you dont pay, can[t] even put a single widget!!' (1★); paywall-shape complaints 0 of 110 before, 6 after; §8.8 #3 put the widget back in the free tier or replace it with an equally visible free surface.")
ext("C009", " Report 79 (Ripples / Checker): interactive, stackable widgets are the app's perfect-score feature (PRAISE_WIDGET 27, 15.70%, 5.00★: 'The widgets are a game changer'; 'thanks to the widgets, I was able to easily keep a track of my study habits'; 'Widgets work effectively without needing to go back into the app'); gating them in 2025 produced the angriest reviews (MON_WIDGET_GATED 2) and a proposed compromise of two free widget sizes; REQ_WIDGET_MORE 5 (smaller/compact widgets) shipped in v2.5.0.")
ext("C007", " Report 79 (Ripples / Checker): a 3-board free cap held for 770 days and converted on its own ('upgraded for more boards and to support the developer'); MON_FREE_GENEROUS 10 at 5.00★; the same cap read as a wall only after the widget left the free tier ([[C297]]).")
ext("C222", " Report 79 (Ripples / Checker): the 3-board cap was tolerated ('Man kann aber auch gut ohne Leben'; 'without huge limitations') while widgets were free and rejected ('totaal niks') once they were not — the pressure valve here was the free widget, and removing it is what broke the cap.")
ext("C003", " Report 79 (Ripples / Checker): MON_ONETIME_PRAISE 12 (6.98%, 4.67★), 9 in year one — 'the premium subscription is a one time 10 dollar payment is incredible'; 'in comparison to other habit trackers that are subscription based'; 'best of all — it's a one time purchase!!'; 7 of 12 frame it as the reason to choose this app over rivals; the listing then added Plus Monthly $2.99 / Yearly $9.99 beside a $24.99 lifetime and the corpus records the arrival ('Nutteloos zonder subscriptie'; 'after a while it turns out I have to pay a monthly subscription'); §8.6 E5 lifetime-forward paywall: show Lifetime first and measure whether the 'no subscription' audience converts higher.")
ext("C186", " Report 79 (Ripples / Checker): 'Lifetime purchase doesn't work. Restore purchases doesn't work. Developer doesn't respond' (1★, 2026-01-01) — consistent with a migration failure when subscription SKUs arrived, though one review is not a mechanism; whether one-time buyers were grandfathered is an open research question (§8.7).")
ext("C294", " Report 79 (Ripples / Checker): year-one reviews sold the app as 'no subscriptions… one time payment of $10'; when the model changed the description still said nothing about money at all and the only 'used to be great' review (1★) lists 'the lack of a subscription' among what it lost — 'a market that was sold a specific promise — one payment, no subscription — encountering a different one, with no listing text to mediate the change'.")
ext("C104", " Report 79 (Ripples / Checker): the widget moved behind the wall and subscription SKUs appeared with zero listing text — MON_UNEXPECTED 2 (2.00★: 'after a while it turns out I have to pay'), MON_BAIT_SWITCH 1 ('Just charge for the download instead of the bait and switch'); two reviewers describe the free tier incompatibly fifteen days apart ('not able to use the app whatsoever for free', 1★ vs 'De momento uso la opción gratuita… súper útil', 5★) — a disclosure problem.")
ext("C218", " Report 79 (Ripples / Checker): the description runs five headed sections and contains no monetization paragraph whatsoever — no free-tier limit, no Plus, no subscription, no price; §8.1.2 four sentences would close it: what the free tier includes, that the board limit is three, what Plus adds, and that both a subscription and a one-time option exist — 'the cheapest high-value change in the report'.")
ext("C236", " Report 79 (Ripples / Checker): the 3-board cap and the paid widget are undisclosed in a description with no money text; §8.6 E2 disclosure A/B measuring the 1★ rate, not installs.")
ext("C177", " Report 79 (Ripples / Checker): five SKUs under three product names (Powerpack $9.99, Ripples Plus Lifetime $24.99, Plus Monthly $2.99, Plus Yearly $9.99, Powerpack Family $17.99) with no billing period shown against any; nine reviews use six different names for the paid tier and two incompatible billing models ('the premium subscription… a one time 10 dollar payment' in one sentence; '$10 for a lifetime subscription'; 'Чекер+'; 'die Vollversion'); 'A customer who cannot tell whether they are buying a subscription cannot consent to buying one'; a 'Чекер+' tier existed under the old app name before today's 'Ripples Plus'.")
ext("C139", " Report 79 (Ripples / Checker): the developer's own v2.7.0 note (2026-09-03) — 'Fixed an issue where Ripples+ features would sometimes become locked while the device was offline' — corroborates MON_ENTITLEMENT_FAIL 3 (every one 1★, 33.3% of stated payers); §8.1.1 an offline grace period for verified entitlements and an in-app 'my purchases' state showing what is owned and when it was verified.")
ext("C033", " Report 79 (Ripples / Checker): U:paid_broken 4 (2.33%), mean 1.00★ — the only theme where every review is one star, and 4 of 11 1★ overall: 'I paid for the pro features but still features are not unlocked. Restore purchase is also not working' (2024-11); 'Lifetime purchase doesn't work. Restore purchases doesn't work. Developer doesn't respond' (2026-01); 'Estafa — Pagué por la versión premium pero no puedo usarla en mis dos celulares' (2026-06); a recurring class over 19 months, not one build; 3 of 9 stated payers; §8.8 #1 'make purchases and restores work, everywhere, including offline'.")
ext("C065", " Report 79 (Ripples / Checker): the 11 purchase-evidence reviews average 3.55★ vs corpus 4.599 — the only substantial segment below the corpus — produced entirely by four broken transactions: five of nine stated payers 5★, four 1★, none 2–4 ('paying this developer is, on the evidence of this corpus, a binary experience'); satisfied payers praise craft at the corpus rate; titles 'Estafa' and 'No part of the app is free' are what a prospective buyer reads.")
ext("C271", " Report 79 (Ripples / Checker): 'Pagué por la versión premium pero no puedo usarla en mis dos celulares' (1★, titled 'Estafa') — a paid entitlement unusable on the buyer's second device; a Family SKU exists yet no review mentions Family Sharing.")
ext("C089", " Report 79 (Ripples / Checker): an AppAdvice free-lifetime promotion (2025-02-25) that could not be redeemed produced a 1★ (MON_PROMO_FAIL) from a user who also could not find directions; a competition-win giveaway produced a disclosed, neutral 5★ — 'a promo that fails is worse than no promo'.")
ext("C094", " Report 79 (Ripples / Checker): solicitation confirmed by the corpus — two reviewers describe the in-app prompt and both rated 1★ specifically because of it: 'I always leave one star reviews for apps that harass me with 'enjoying the app? Please leave a review' popups. It's gross. Change that behavior and I'll update this to 5 stars'; 'I keep getting the review prompt after every check in. Lowering to 1 stars until fixed' — 18.2% of the app's worst ratings from a growth mechanic; the 83.14% 5★ share is 'what a satisfied user gives when asked at a good moment'; §8.1.4 cap it once per user, never after a check-in, never after a user has already rated.")
ext("C240", " Report 79 (Ripples / Checker): the review prompt fired 'after every check in' — the completion moment — and a previously-5★ paying user dropped to 1★ until it stops.")
ext("C150", " Report 79 (Ripples / Checker): never re-prompt someone who has already rated — 'i already rated this highly, but now I keep getting the review prompt' (1★).")
ext("C175", " Report 79 (Ripples / Checker): U:defect_any 0.9% (E1) → 0.0% → 19.5% (E3, mean 2.50★); 8 of 9 defects after v2.1.0 (2026-02-11), 'a major internal overhaul' whose own notes warn 'widgets and custom shortcuts need to be re-configured', followed within four days by a 'Deduplicate data' tool 'as some people reported duplicated boards and check-ins'; a crash on board creation fixed by name 11 days later; a self-described daily user: 'I loved how easy it was to use, how reliable it was… Now UI bugs have made it unusable' (1★); the two worst-rated eras follow a rename and an overhaul.")
ext("C034", " Report 79 (Ripples / Checker): DEF_DATA_LOSS 3 (1.74%, mean 2.00★), all in the last seven months — 'All data gone after updating to ios 18.4' (1★; later recovered by iCloud sync), 'Han borrado los datos previos de antes del cambio de nombre' (1★, attributing the loss to the rename), 'My old boards got taken down in an update… Is there anyway I can get them back? I had a nice streak going' (4★, matching a v2.6.2 stability fix for year-old builds); 'for a habit tracker, whose entire value is an unbroken record, this is the most damaging defect class'; an archive/restore feature shipped in v2.3.0 and nothing suggests users know it exists.")
ext("C039", " Report 79 (Ripples / Checker): multiple reminders — asked by three reviewers in 2024 — shipped in v2.2.0 (2026-03-01) and generated two reliability complaints five and six weeks later (DEF_NOTIF_FAIL 2, 3.50★: 'maybe is a bug I would like a anwser') — a newly shipped requested feature created its own defect class.")
ext("C142", " Report 79 (Ripples / Checker): a 2026-07-05 review asks for 'cloud sync, so data can be backed up and synchronized across devices' — iCloud sync has shipped since at least 2024-10-14, is praised by three reviewers and is a headed section of the description; an archive/restore feature (v2.3.0) is likewise unknown to a user asking for lost boards back.")
ext("C043", " Report 79 (Ripples / Checker): REQ_WEEKLY_SCHEDULE 3 (4.67★, 2024-10 → 2026-07), partial only (v2.4.0 lets you disable streak/consistency; no weekly target): 'a gym habit done 3×/week can never build a streak, so the app's core feedback loop breaks for non-daily habits'; 'Wenn ich einzelne Tage skippen könnte, oder ein Wochenziel festlegen… Das wäre der 5. Stern für mich' (4★) — one of only two pre-committed-star requests in the corpus.")
ext("C022", " Report 79 (Ripples / Checker): REQ_WATCH 3 (4.33★, 2024-12 → 2026-06) — 'quasi unentbehrlich' for fast capture; 'Bitte ganz nach oben auf die Prioritätenliste!!!! (dann gibt's auch ✱✱✱✱✱)' (4★); the listing is iPhone-only; §8.3 'the app's whole value is low-friction check-in and the Watch is where that friction is lowest'; §8.7 whether the Watch actually converts or is a stated preference.")
